func minCut(s string) int {
	n := len(s)
	pal := make([][]bool, n)
	for i := range pal {
		pal[i] = make([]bool, n)
	}
	for i := n - 1; i >= 0; i-- {
		for j := i; j < n; j++ {
			if s[i] == s[j] && (j-i <= 2 || pal[i+1][j-1]) {
				pal[i][j] = true
			}
		}
	}
	dp := make([]int, n)
	for i := 0; i < n; i++ {
		if pal[0][i] {
			dp[i] = 0
			continue
		}
		dp[i] = i
		for j := 0; j < i; j++ {
			if pal[j+1][i] && dp[j]+1 < dp[i] {
				dp[i] = dp[j] + 1
			}
		}
	}
	return dp[n-1]
}

