func build(vals []string) *TreeNode {
	if len(vals) == 0 || vals[0] == "null" {
		return nil
	}
	root := &TreeNode{Val: atoi(vals[0])}
	queue := []*TreeNode{root}
	head, i := 0, 1
	for head < len(queue) && i < len(vals) {
		node := queue[head]
		head++
		if i < len(vals) {
			if vals[i] != "null" {
				node.Left = &TreeNode{Val: atoi(vals[i])}
				queue = append(queue, node.Left)
			}
			i++
		}
		if i < len(vals) {
			if vals[i] != "null" {
				node.Right = &TreeNode{Val: atoi(vals[i])}
				queue = append(queue, node.Right)
			}
			i++
		}
	}
	return root
}

