		ones := len(s) - zeros
		for i := m; i >= zeros; i-- {
			for j := n; j >= ones; j-- {
				if v := dp[i-zeros][j-ones] + 1; v > dp[i][j] {
					dp[i][j] = v
				}
			}
		}
	}
	return dp[m][n]
}

