		return 0
	}
	bag := (total + target) / 2
	dp := make([]int, bag+1)
	dp[0] = 1
	for _, x := range nums {
		for j := bag; j >= x; j-- {
			dp[j] += dp[j-x]
		}
	}
	return dp[bag]
}

